import { cn } from '@/lib/utils'

export function OnCard({ className, children, onClick, ...props }: React.HTMLAttributes<HTMLDivElement> & { onClick?: () => void }) {
  return (
    <div
      className={cn(
        'rounded-xl border border-border/50 bg-card/50 p-5 transition-colors hover:border-border cursor-pointer',
        className
      )}
      onClick={onClick}
      {...props}
    >
      {children}
    </div>
  )
}

export function OnCardHeader({ className, children, ...props }: React.HTMLAttributes<HTMLDivElement>) {
  return <div className={cn('mb-3 flex items-center justify-between', className)} {...props}>{children}</div>
}

export function OnCardTitle({ className, children, ...props }: React.HTMLAttributes<HTMLHeadingElement>) {
  return <h3 className={cn('text-sm font-semibold text-foreground', className)} {...props}>{children}</h3>
}

export function OnCardDescription({ className, children, ...props }: React.HTMLAttributes<HTMLParagraphElement>) {
  return <p className={cn('text-xs text-muted-foreground leading-relaxed line-clamp-2', className)} {...props}>{children}</p>
}

export function OnCardFooter({ className, children, ...props }: React.HTMLAttributes<HTMLDivElement>) {
  return <div className={cn('mt-4 pt-3 border-t border-border/30 flex items-center justify-between', className)} {...props}>{children}</div>
}

import { cn } from '@/lib/utils'

const COLORS = {
  success: 'bg-green-500',
  warning: 'bg-amber-500',
  danger: 'bg-red-500',
  info: 'bg-cyan-500',
  muted: 'bg-muted-foreground',
} as const

export function StatusDot({ status = 'muted', size = 8, className }: { status?: keyof typeof COLORS; size?: number; className?: string }) {
  return <div className={cn('rounded-full shrink-0', COLORS[status], className)} style={{ width: size, height: size }} />
}

export function urgencyColor(v: number) {
  if (v >= 70) return '#ef4444'
  if (v >= 40) return '#f59e0b'
  return '#7ed957'
}

export function UrgencyBar({ value, height = 3 }: { value: number; height?: number }) {
  return (
    <div className='flex items-center gap-2'>
      <div className='flex-1 rounded-full overflow-hidden' style={{ height, background: 'rgba(255,255,255,0.06)' }}>
        <div style={{ height: '100%', width: `${value}%`, background: urgencyColor(value), borderRadius: height, transition: 'width 0.3s' }} />
      </div>
      <span style={{ fontSize: 9, fontWeight: 600, color: urgencyColor(value) }}>{value}</span>
    </div>
  )
}

import { cn } from '@/lib/utils'

export function StatCard({ label, value, icon, color = 'text-foreground', className }: { label: string; value: string | number; icon: React.ReactNode; color?: string; className?: string }) {
  return (
    <div className={cn('rounded-xl border border-border/50 bg-card/50 p-4', className)}>
      <div className='flex items-center gap-2 mb-1'>
        <span className={color}>{icon}</span>
        <span className='text-[11px] text-muted-foreground uppercase tracking-wider'>{label}</span>
      </div>
      <div className='text-2xl font-bold text-foreground'>{value}</div>
    </div>
  )
}

export interface SubNavItem {
  key: string
  label: string
  icon: React.ReactNode
  color: string
}

export function SubNav({ items, active, onChange }: { items: SubNavItem[]; active: string; onChange: (key: string) => void }) {
  return (
    <div style={{ width: 220, borderLeft: '1px solid rgba(255,255,255,0.04)', paddingLeft: 20, flexShrink: 0 }}>
      <div style={{ position: 'sticky', top: 80 }}>
        <p style={{ fontSize: 10, fontWeight: 600, color: 'rgba(255,255,255,0.25)', textTransform: 'uppercase', letterSpacing: '0.08em', marginBottom: 12 }}>Navigation</p>
        <div style={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
          {items.map(item => (
            <button
              key={item.key}
              onClick={() => onChange(item.key)}
              style={{
                display: 'flex', alignItems: 'center', gap: 10,
                padding: '8px 12px', borderRadius: 8,
                background: active === item.key ? 'rgba(255,255,255,0.04)' : 'transparent',
                border: 'none', cursor: 'pointer', textAlign: 'left', width: '100%',
              }}
            >
              <span style={{ color: active === item.key ? item.color : 'rgba(255,255,255,0.3)' }}>{item.icon}</span>
              <span style={{ fontSize: 13, fontWeight: active === item.key ? 600 : 400, color: active === item.key ? '#fff' : 'rgba(255,255,255,0.4)' }}>{item.label}</span>
              {active === item.key && <div style={{ marginLeft: 'auto', width: 4, height: 4, borderRadius: 2, background: item.color }} />}
            </button>
          ))}
        </div>
      </div>
    </div>
  )
}

export function FogBackground() {
  return (
    <>
      <div className='fog-layer' style={{ position: 'fixed', inset: 0, pointerEvents: 'none', zIndex: 0, background: 'radial-gradient(ellipse at 20% 60%, rgba(126,217,87,0.07) 0%, transparent 55%)', animation: 'fog-drift-1 12s ease-in-out infinite alternate' }} />
      <div className='fog-layer' style={{ position: 'fixed', inset: 0, pointerEvents: 'none', zIndex: 0, background: 'radial-gradient(ellipse at 80% 30%, rgba(126,217,87,0.05) 0%, transparent 50%)', animation: 'fog-drift-2 16s ease-in-out infinite alternate' }} />
      <div className='fog-layer' style={{ position: 'fixed', inset: 0, pointerEvents: 'none', zIndex: 0, background: 'radial-gradient(ellipse at 50% 90%, rgba(20,184,166,0.04) 0%, transparent 50%)', animation: 'fog-drift-3 20s ease-in-out infinite alternate' }} />
      <style>{`
        @keyframes fog-drift-1 { 0% { transform: translate(0,0) scale(1); opacity:.6; } 100% { transform: translate(40px,-30px) scale(1.15); opacity:1; } }
        @keyframes fog-drift-2 { 0% { transform: translate(0,0) scale(1.1); opacity:.5; } 100% { transform: translate(-50px,20px) scale(1); opacity:.9; } }
        @keyframes fog-drift-3 { 0% { transform: translate(0,0) scale(1); opacity:.4; } 100% { transform: translate(30px,-40px) scale(1.2); opacity:.7; } }
        @media (prefers-reduced-motion: reduce) { .fog-layer { animation: none !important; } }
      `}</style>
    </>
  )
}
